def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
protected={p.relative_to(site):digest(p) for p in (site/'games').rglob('*') if p.is_file()};protected[Path('manifest.webmanifest')]=digest(site/'manifest.webmanifest')
